<div class="relative w-full h-[380px] rounded-2xl overflow-hidden shadow-inner bg-surface-dim">
<img class="w-full h-full object-cover" data-alt="Persian male senior surgeon in a modern clean medical office with scrubs and stethoscope on a high definition video call consultation, warm welcoming clinical atmosphere with medical monitors showing MRI scan in the background, soft turquoise accents" src="https://lh3.googleusercontent.com/aida-public/AB6AXuB8UaY0dDYuuWXQuY7KcIGxDfb0n_Bb61WTNWl5_A585op5ygJw0ljlaONADLDh9ZvWJsVM3mkwg8-V-qu6dFlPsTp0TmlvRpaAY5AatBgVfj_-ZqcZUm2u9JJoZcVwXNNGBNB_JraGulKWqF_FYqJ-U5t62-7xn8K1v7xAIQAmRgcBp8Rworf0x-AN0pmX3ucvxlUV-1NULLOccWzmi9hH0erZfR_E-6vpGkSDXKU"/>
